const FRESH_STATE = () => ({
  score: 0,
  unlocked: [],
  activeBadge: null,
  activeSkin: 'default',
  hints: 2,
  purchases: {},
  redeemed: {},
  history: { rounds: 0, correct: 0, answered: 0, best: 0 },
  games: [],
  trades: [],
  wrongItems: {},
  redeemed: {}
});
function ensureState(s) {
  if (!s.purchases) s.purchases = {};
  if (!s.redeemed || typeof s.redeemed !== 'object') s.redeemed = {};
  if (!Array.isArray(s.games)) s.games = [];
  if (!Array.isArray(s.trades)) s.trades = [];
  if (!s.history) s.history = { rounds: 0, correct: 0, answered: 0, best: 0 };
  if (!s.pendingRound) s.pendingRound = null;
  if (typeof s.hints !== 'number') s.hints = 2;
  if (!s.wrongItems || typeof s.wrongItems !== 'object') s.wrongItems = {};
  if (!s.redeemed || typeof s.redeemed !== 'object') s.redeemed = {};
  /* R63 共享模块状态：老存档无这些字段时惰性初始化为 {} */
  if (!s.modScores || typeof s.modScores !== 'object' || Array.isArray(s.modScores)) s.modScores = {};
  if (!s.modCounts || typeof s.modCounts !== 'object' || Array.isArray(s.modCounts)) s.modCounts = {};
  if (!s.modBests || typeof s.modBests !== 'object' || Array.isArray(s.modBests)) s.modBests = {};
  if (!s.modLimitsUsed || typeof s.modLimitsUsed !== 'object' || Array.isArray(s.modLimitsUsed)) s.modLimitsUsed = {};
  return s;
}

/* ===== R63 共享模块状态 / 次数限制（冻结接口，各模块一律调用，勿改签名） ===== */
/* 模块 id 固定：learn 小课堂 / classic 小达人 / flychess 飞行棋 / runner 跑酷 / matches 消消乐 */
function isAdminUnlocked() {
  try { return sessionStorage.getItem(LS_ADMIN_UNLOCK) === '1'; } catch (e) { return false; }
}
/* 该模块单账号次数限制；管理员解锁时返回 Infinity。0=不限制 */
function moduleLimit(mod, lv) {
  if (isAdminUnlocked()) return Infinity;
  /* R65：难度级 limit>0 时优先用；否则回退模块级（默认不设=沿用模块限制） */
  if (lv && typeof lv.limit === 'number' && lv.limit > 0) return lv.limit;
  var lim = 0;
  if (mod === 'classic') lim = (config.settings && typeof config.settings.classicRoundLimit === 'number') ? config.settings.classicRoundLimit : 0;
  else if (mod === 'learn') lim = (config.learn && typeof config.learn.perAccountLimit === 'number') ? config.learn.perAccountLimit : 0;
  else if (mod === 'flychess') lim = (config.flychess && typeof config.flychess.perAccountLimit === 'number') ? config.flychess.perAccountLimit : 0;
  else if (mod === 'runner') lim = (config.runner && typeof config.runner.perAccountLimit === 'number') ? config.runner.perAccountLimit : 0;
  else if (mod === 'matches') lim = (config.matches && typeof config.matches.perAccountLimit === 'number') ? config.matches.perAccountLimit : 0;
  return lim || 0;
}
/* R65：计数键——模块级用 mod，难度级用 mod@lvId（兼容老存档 modLimitsUsed[mod]） */
function _limitKey(mod, lvId) { return lvId ? (mod + '@' + lvId) : mod; }
/* 限制消耗计数（learn 每题 +1，其余每局 +1），重置时清零 */
function moduleCount(mod, lvId) { return (state.modLimitsUsed && state.modLimitsUsed[_limitKey(mod, lvId)]) || 0; }
function bumpModuleCount(mod, lvId) {
  if (!state.modLimitsUsed) state.modLimitsUsed = {};
  var k = _limitKey(mod, lvId);
  state.modLimitsUsed[k] = (state.modLimitsUsed[k] || 0) + 1;
  saveState();
}
/* 游玩次数统计（learn 每答一组 +1，其余每局 +1），不受重置影响 */
function playCount(mod) { return (state.modCounts && state.modCounts[mod]) || 0; }
function bumpPlayCount(mod) {
  if (!state.modCounts) state.modCounts = {};
  state.modCounts[mod] = (state.modCounts[mod] || 0) + 1;
  saveState();
}
function canPlayModule(mod, lv) {
  if (isAdminUnlocked()) return true;
  var lim = moduleLimit(mod, lv);
  if (!lim || lim <= 0) return true; /* 0=不限制 */
  return moduleCount(mod, lv && lv.id) < lim;
}
/* 该模块累计积分 */
function moduleScore(mod) { return (state.modScores && state.modScores[mod]) || 0; }
/* 模块加分：同时累加进 modScores[mod] 与总积分 state.score（总积分=各模块之和） */
function addModuleScore(mod, pts) {
  pts = Number(pts) || 0;
  if (!state.modScores) state.modScores = {};
  state.modScores[mod] = (state.modScores[mod] || 0) + pts;
  state.score = (state.score || 0) + pts;
  saveState();
}
/* 该项目历史最高单局分：各模块结算时自行调用 recordModuleBest(mod, earned) */
function recordModuleBest(mod, earned) {
  earned = Number(earned) || 0;
  if (!state.modBests) state.modBests = {};
  if (earned > (state.modBests[mod] || 0)) state.modBests[mod] = earned;
  saveState();
}
/* 模块化重置：只清该模块累计积分 + 限制消耗计数；modCounts/modBests 不动。
   从总积分中扣回该模块累计分，保持 总积分=各模块之和。 */
function resetModuleScore(mod) {
  if (!state.modScores) state.modScores = {};
  var delta = state.modScores[mod] || 0;
  state.score = Math.max(0, (state.score || 0) - delta);
  state.modScores[mod] = 0;
  if (!state.modLimitsUsed) state.modLimitsUsed = {};
  state.modLimitsUsed[mod] = 0;
  saveState();
}
let currentUser = '';
function getAccounts() { return loadJSON(LS_ACCOUNTS, {}); }
function setCurrentUser(name) {
  currentUser = name || '';
  if (currentUser) localStorage.setItem(LS_CURRENT_USER, currentUser);
  else localStorage.removeItem(LS_CURRENT_USER);
}
function loadStateByUser() {
  if (currentUser) {
    const acc = getAccounts()[currentUser];
    if (acc && acc.data) return ensureState(acc.data);
  }
  return ensureState(loadJSON(LS_STATE, FRESH_STATE()));
}
