function rt3dInit() {
  if (typeof THREE === 'undefined') { toast('3D 引擎未加载，请重新打开页面', 'bad', null, 3000); return; }
  const stage = $('#rt-stage');
  const old = $('#rt-canvas');
  if (old) old.style.display = 'none';
  /* R60：预热全部垃圾贴图，确保跑道收集物是真实垃圾图 */
  (config.items || []).forEach(function (it) { if (it && it.img) { try { rt3dItemImgTex(it.img, '#888'); } catch (e) {} } });
  const w = Math.max(320, Math.min(780, stage.clientWidth || 780));
  const h = Math.round(w * (window.innerWidth <= 760 ? 0.5 : 0.56));
  const renderer = new THREE.WebGLRenderer({ antialias: true });
  renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
  renderer.setSize(w, h);
  renderer.domElement.id = 'rt3d-canvas';
  renderer.domElement.style.width = '100%';
  renderer.domElement.style.height = 'auto';
  renderer.domElement.style.borderRadius = '20px';
  renderer.domElement.style.boxShadow = '0 12px 30px rgba(120,160,240,.3)';
  renderer.domElement.style.cursor = 'pointer';
  renderer.domElement.style.touchAction = 'none';
  if (stage) stage.insertBefore(renderer.domElement, old || null);
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x9fd4ff);
  scene.fog = new THREE.Fog(0x9fd4ff, 60, 240);
  const camera = new THREE.PerspectiveCamera(72, w / h, 0.1, 300);
  camera.position.set(0, 1.55, 0);
  camera.lookAt(0, 0.9, -24);
  scene.add(new THREE.AmbientLight(0xffffff, 0.8));
  const sunLight = new THREE.DirectionalLight(0xfff3d6, 1.15);
  sunLight.position.set(6, 18, 10);
  scene.add(sunLight);
  /* 地面：三车道条纹 */
  const groundTex = rt3dGroundTex();
  groundTex.wrapS = groundTex.wrapT = THREE.RepeatWrapping;
  const ground = new THREE.Mesh(
    new THREE.PlaneGeometry(9.2, 200),
    new THREE.MeshBasicMaterial({ map: groundTex })
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.set(0, 0, -80);
  scene.add(ground);
  /* 两侧草地 */
  [-1, 1].forEach((side) => {
    const g = new THREE.Mesh(
      new THREE.PlaneGeometry(90, 200),
      new THREE.MeshBasicMaterial({ color: 0xa5e08f })
    );
    g.rotation.x = -Math.PI / 2;
    g.position.set(side * 30, -0.03, -80);
    scene.add(g);
  });
  /* 路侧景物 */
  const props = new THREE.Group();
  for (let z = -8; z > -140; z -= 8.5) {
    const side = (Math.abs(z) % 17) < 8.5 ? 1 : -1;
    const kind = Math.abs(z) % 3;
    const x = side * 5.1;
    if (kind === 0) {
      const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.22, 1.2, 6), new THREE.MeshLambertMaterial({ color: 0x8a5a2b }));
      trunk.position.set(x, 0.6, z);
      const crown = new THREE.Mesh(new THREE.ConeGeometry(0.9, 1.9, 7), new THREE.MeshLambertMaterial({ color: 0x62c25a }));
      crown.position.set(x, 1.95, z);
      props.add(trunk, crown);
    } else if (kind === 1) {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 2.4, 6), new THREE.MeshLambertMaterial({ color: 0xdcdfef }));
      pole.position.set(x, 1.2, z);
      const head = new THREE.Mesh(new THREE.SphereGeometry(0.22, 10, 8), new THREE.MeshLambertMaterial({ color: 0xffe08a }));
      head.position.set(x, 2.4, z);
      props.add(pole, head);
    } else {
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 1.7, 6), new THREE.MeshLambertMaterial({ color: 0xffb3c6 }));
      pole.position.set(x, 0.85, z);
      const ball = new THREE.Mesh(new THREE.SphereGeometry(0.36, 10, 8), new THREE.MeshLambertMaterial({ color: 0xff7eb3 }));
      ball.position.set(x, 1.8, z);
      props.add(pole, ball);
    }
  }
  scene.add(props);
  /* 云 */
  const clouds = new THREE.Group();
  for (let i = 0; i < 7; i++) {
    const cl = new THREE.Mesh(new THREE.SphereGeometry(2 + Math.random() * 1.8, 10, 8), new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.88 }));
    cl.position.set(-16 + Math.random() * 32, 9 + Math.random() * 8, -22 - Math.random() * 90);
    clouds.add(cl);
  }
  scene.add(clouds);
  /* 太阳 */
  const sunSprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: rt3dSunTex(), transparent: true, depthWrite: false }));
  sunSprite.scale.set(8, 8, 1);
  sunSprite.position.set(17, 18, -100);
  scene.add(sunSprite);
  rt3d = { renderer, scene, camera, groundTex, props, clouds };
  /* 事件：点击跳跃 */
  renderer.domElement.addEventListener('mousedown', () => rtJump());
  renderer.domElement.addEventListener('touchstart', (e) => { if (rt && rt.running) { rtJump(); if (e.cancelable) e.preventDefault(); } }, { passive: false });
}
