const ITEM_TEX_B64 = {"assets/items/hazardous-0.png":"data:image/png;base64,","assets/items/hazardous-1.png":"data:image/png;base64,","assets/items/hazardous-2.png":"data:image/png;base64,","assets/items/hazardous-3.png":"data:image/png;base64,","assets/items/hazardous-4.png":"data:image/png;base64,","assets/items/hazardous-5.png":"data:image/png;base64,","assets/items/kitchen-0.png":"data:image/png;base64,","assets/items/kitchen-1.png":"data:image/png;base64,","assets/items/kitchen-2.png":"data:image/png;base64,","assets/items/kitchen-3.png":"data:image/png;base64,","assets/items/kitchen-4.png":"data:image/png;base64,","assets/items/kitchen-5.png":"data:image/png;base64,","assets/items/other-0.png":"data:image/png;base64,","assets/items/other-1.png":"data:image/png;base64,","assets/items/other-2.png":"data:image/png;base64,","assets/items/other-3.png":"data:image/png;base64,","assets/items/other-4.png":"data:image/png;base64,","assets/items/other-5.png":"data:image/png;base64,","assets/items/recyclable-0.png":"data:image/png;base64,","assets/items/recyclable-1.png":"data:image/png;base64,","assets/items/recyclable-2.png":"data:image/png;base64,","assets/items/recyclable-3.png":"data:image/png;base64,","assets/items/recyclable-4.png":"data:image/png;base64,","assets/items/recyclable-5.png":"data:image/png;base64,"};
