function saveConfigSilently(msg) {
  const ok = saveJSON(LS_CONFIG, config);
  if (msg) toast(msg, ok ? 'good' : 'bad');
}

/* ---------- 分享编辑配置（仅 config，不含账户/进度/历史等数据） ---------- */
/* 递归对比：只保留与默认不同的字段（数组整体比较；嵌套对象递归） */
function diffConfig(base, cur) {
  const out = {};
  let changed = false;
  const keys = new Set(Object.keys(base || {}).concat(Object.keys(cur || {})));
  for (const k of keys) {
    const bv = base ? base[k] : undefined;
    const cv = cur ? cur[k] : undefined;
    if (JSON.stringify(bv) === JSON.stringify(cv)) continue;
    if (bv && cv && typeof bv === 'object' && typeof cv === 'object' &&
        !Array.isArray(bv) && !Array.isArray(cv)) {
      const sub = diffConfig(bv, cv);
      if (Object.keys(sub).length) { out[k] = sub; changed = true; }
    } else {
      out[k] = cv;
      changed = true;
    }
  }
  return changed ? out : {};
}
/* 深合并：patch 覆盖 base（数组整体替换），用于把分享的 diff 应用到默认配置上 */
function mergeConfig(base, patch) {
  if (patch === undefined || patch === null) return base;
  if (Array.isArray(patch) || typeof patch !== 'object') return patch;
  const out = {};
  const keys = new Set(Object.keys(base || {}).concat(Object.keys(patch)));
  for (const k of keys) {
    const bv = base ? base[k] : undefined;
    const pv = patch[k];
    if (pv === undefined) { out[k] = bv; continue; }
    if (bv && pv && typeof bv === 'object' && typeof pv === 'object' &&
        !Array.isArray(bv) && !Array.isArray(pv)) {
      out[k] = mergeConfig(bv, pv);
    } else {
      out[k] = pv;
    }
  }
  return out;
}
function shareConfigNow() {
  try {
    const payload = JSON.stringify(diffConfig(DEFAULT_CONFIG, config));
    const code = btoa(unescape(encodeURIComponent(payload)))
      .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    const url = location.origin + location.pathname + '#cfg=' + code;
    const showLink = () => {
      try { prompt('复制以下分享链接，发送到新设备打开即可自动应用编辑内容：', url); }
      catch (e) { toast('分享链接已生成，请复制地址栏链接', 'info'); }
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(url).then(() => {
        toast('分享链接已复制，发送到新设备打开即可同步编辑内容', 'good', null, 4000);
      }).catch(showLink);
    } else showLink();
  } catch (e) {
    toast('分享失败：' + e.message, 'bad');
  }
}
function applyShareConfig() {
  let code = null;
  const m = location.hash.match(/[#&]cfg=([^&]+)/);
  if (m) code = m[1];
  if (!code) return false;
  try {
    let b64 = code.replace(/-/g, '+').replace(/_/g, '/');
    while (b64.length % 4) b64 += '=';
    const json = decodeURIComponent(escape(atob(b64)));
    const parsed = JSON.parse(json);
    if (!parsed || typeof parsed !== 'object' ||
        !Array.isArray(parsed.bins) || !Array.isArray(parsed.items) ||
        !Array.isArray(parsed.mall) || !parsed.settings) return false;
    config = ensureConfig(mergeConfig(DEFAULT_CONFIG, parsed));
    saveJSON(LS_CONFIG, config);
    try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}
    return true;
  } catch (e) { return false; }
}

el.editItems.addEventListener('input', (e) => {
  const t = e.target;
  const card = t.closest('.edit-card');
  if (!card) return;
  const id = card.dataset.id;
  const item = config.items.find((i) => i.id === id);
  if (!item) return;
  if (t.dataset.f === 'name') item.name = t.value.trim() || '未命名';
  if (t.dataset.f === 'bin') item.bin = t.value;
  if (t.dataset.f === 'points') item.points = Math.max(1, parseInt(t.value, 10) || 1);
  if (t.dataset.f === 'q') item.q = t.value.trim();
  if (t.dataset.f === 'builtin') {
    item.img = t.value;
    card.querySelector('[data-f="preview"]').src = item.img;
    card.querySelector('[data-f="imgurl"]').value = '';
  }
  if (t.dataset.f === 'imgurl') {
    item.img = t.value.trim();
    card.querySelector('[data-f="preview"]').src = item.img || 'assets/items/recyclable-0.png';
  }
  saveConfigSilently();
});

el.editItems.addEventListener('change', (e) => {
  const t = e.target;
  const card = t.closest('.edit-card');
  if (!card) return;
  const id = card.dataset.id;
  const item = config.items.find((i) => i.id === id);
  if (!item) return;
  if (t.dataset.f === 'upload' && t.files && t.files[0]) {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const max = 160;
        const scale = Math.min(1, max / Math.max(img.width, img.height));
        canvas.width = Math.max(1, Math.round(img.width * scale));
        canvas.height = Math.max(1, Math.round(img.height * scale));
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        item.img = canvas.toDataURL('image/png');
        card.querySelector('[data-f="preview"]').src = item.img;
        card.querySelector('[data-f="imgurl"]').value = '';
        card.querySelector('[data-f="builtin"]').value = '';
        saveConfigSilently('图片已更新并保存');
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(t.files[0]);
  }
});

el.editItems.addEventListener('click', (e) => {
  const btn = e.target.closest('button[data-act]');
  if (!btn) return;
  if (btn.dataset.act === 'del-item') {
    const card = btn.closest('.edit-card');
    const id = card.dataset.id;
    config.items = config.items.filter((i) => i.id !== id);
    saveConfigSilently('已删除');
    renderEditItems();
    renderBins();
  } else if (btn.dataset.act === 'add-item') {
    const base = config.items[0] || { bin: config.bins[0].id, points: 10 };
    const newItem = {
      id: 'custom-' + Date.now(),
      name: '新物品',
      img: BUILTIN_ICONS[0][1],
      bin: base.bin,
      points: base.points || 10
    };
    config.items.push(newItem);
    saveConfigSilently('已新增，填好内容即自动保存');
    renderEditItems();
    const newCard = el.editItems.querySelector('.edit-card[data-id="' + newItem.id + '"]');
    if (newCard) newCard.querySelector('[data-f="name"]').focus();
  }
});

