    fc.rankPoints = $('#set-fc-rank').value.split(/[,，]/).map((x) => parseInt(x.trim(), 10) || 0).filter((x, i) => i < 4 && x > 0);
    if (!fc.rankPoints.length) fc.rankPoints = [30, 20, 10, 5];
    fc.questions = parseQuestions($('#set-fc-q').value);
    rn.name = $('#set-rt-name').value.trim() || '垃圾分类跑酷';
    rn.duration = Math.max(10, Math.min(300, parseInt($('#set-rt-dur').value, 10) || 60));
    rn.goodPoints = Math.max(1, Math.min(999, parseInt($('#set-rt-good').value, 10) || 10));
    rn.badPoints = Math.max(1, Math.min(999, parseInt($('#set-rt-bad').value, 10) || 5));
    rn.targetChangeMs = Math.max(2000, Math.min(60000, parseInt($('#set-rt-tgt').value, 10) || 8000));
    rn.speed = Math.max(0.3, Math.min(3, parseFloat($('#set-rt-speed').value) || 1));
    if (config.runner) config.runner.levels = parseRtLevels($('#set-rt-levels') ? $('#set-rt-levels').value : '');
    rn.img = $('#set-rt-img').value.trim();
