/* R66 反馈1/5：完成页仅由"5/5 进度条/玩法目录入口点击 + 五模块全部已玩"触发；未全完成则打开目录弹层 */
function r65MaybeShowDone() {
  var panel = $('#play-catalog-panel');
  var allDone = R63_CATALOG.every(function (m) { return r63Played(m); });
  if (allDone) { r65ShowClassicDone(); return; }
  renderPlayCatalogPanel();
  if (panel) panel.classList.remove('is-hidden');
}
/* 玩法目录开关 + 5/5 进度条入口 + 点外部关闭 */
(function () {
  var btn = $('#play-catalog');
  if (btn) btn.addEventListener('click', r65MaybeShowDone);
  var strip = document.querySelector('.hp-bars');
  if (strip) { strip.style.cursor = 'pointer'; strip.addEventListener('click', r65MaybeShowDone); }
  /* R66-B：UI Agent 新增的拉长进度条入口（fixed 在原 #play-catalog 处） */
  var pentry = $('#r66-progress-entry');
  if (pentry) { pentry.style.cursor = 'pointer'; pentry.addEventListener('click', r65MaybeShowDone); }
  /* R68 反馈1：目录弹层按钮事件委托——容器级一次性绑定（innerHTML 重建不丢绑定） */
  var catalogPanel = $('#play-catalog-panel');
  if (catalogPanel) catalogPanel.addEventListener('click', r63CatalogPanelClick);
  document.addEventListener('click', function (e) {
    var panel = $('#play-catalog-panel');
    if (!panel || panel.classList.contains('is-hidden')) return;
    if (e.target && e.target.closest && (e.target.closest('#play-catalog') || e.target.closest('.hp-bars') || e.target.closest('#r66-progress-entry') || e.target.closest('#play-catalog-panel'))) return;
    panel.classList.add('is-hidden');
  });
})();
/* 称号段位弹层（#badge-tiers-panel 由 JS 注入，index.html 未提供容器） */
function r63BuildBadgePanel() {
  if ($('#badge-tiers-panel')) return;
  var p = document.createElement('div');
  p.id = 'badge-tiers-panel'; p.className = 'r63-badge-panel is-hidden';
  var rows = (config.badges || []).map(function (b, i) {
    var next = config.badges[i + 1];
    var range = (i === config.badges.length - 1) ? ((b.min || 0) + ' 分及以上') : ((b.min || 0) + ' ~ ' + (((next && next.min) || 0) - 1) + ' 分');
    return '<div class="r63-badge-row"><span class="r63-badge-min">' + range + '</span><span class="r63-badge-name">' + escapeHtml(b.name || '') + '</span></div>';
  }).join('');
  p.innerHTML = '<div class="r63-badge-card"><div class="r63-badge-head">称号段位<small>按累计积分解锁</small></div>' + rows + '<button type="button" class="btn btn-sm btn-primary r63-badge-close">关闭</button></div>';
  document.body.appendChild(p);
  p.querySelector('.r63-badge-close').addEventListener('click', function () { p.classList.add('is-hidden'); });
  p.addEventListener('click', function (e) { if (e.target === p) p.classList.add('is-hidden'); });
}
(function () {
  var cb = $('#chip-badge');
  if (cb) cb.addEventListener('click', function () {
    r63BuildBadgePanel();
    var p = $('#badge-tiers-panel'); if (p) p.classList.toggle('is-hidden');
  });
})();
