/* ---------- 开局预加载动画（R30）：先把资源全部加载好再放行，避免点进游戏 UI 未加载 ---------- */
(function bootPreload() {
  const boot = document.getElementById('boot');
  if (!boot) return;
  const barFill = document.getElementById('boot-bar-fill');
  const tip = document.getElementById('boot-tip');
  /* R56：加载页下方显示垃圾分类知识文字，点击可切换（管理员可编辑） */
  const tips = (config && config.loadingTips && config.loadingTips.length)
    ? config.loadingTips
    : (DEFAULT_CONFIG.loadingTips || []).slice();
  let tipIdx = -1;
  function nextTip() {
    if (!tip || !tips.length) return;
    tipIdx = (tipIdx + 1) % tips.length;
    tip.textContent = tips[tipIdx];
  }
  nextTip();
  if (tip) tip.addEventListener('click', nextTip);
  /* 收集待加载图片：config 内图片路径/URL + 页面所有 <img> */
  const urls = [];
  const seen = {};
  function add(u) {
    if (!u || typeof u !== 'string') return;
    if (!/^(assets\/|https?:|data:)/.test(u)) return;
    if (seen[u]) return;
    seen[u] = 1;
    urls.push(u);
  }
  (function walk(o) {
    if (!o || typeof o !== 'object') { if (typeof o === 'string') add(o); return; }
    if (Array.isArray(o)) { o.forEach(walk); return; }
    Object.keys(o).forEach(function (k) { walk(o[k]); });
  })(config);
  document.querySelectorAll('img').forEach(function (im) { add(im.getAttribute('src') || im.src); });
  /* R63 标题：读 config.loading.title，DEFAULT_CONFIG 兜底 */
  const bootTitle = boot.querySelector('.boot-title');
  const _ldCfg = (typeof config !== 'undefined' && config.loading) || {};
  const _ldDef = (typeof DEFAULT_CONFIG !== 'undefined' && DEFAULT_CONFIG.loading) || {};
  if (bootTitle) bootTitle.textContent = _ldCfg.title || _ldDef.title || '垃圾分类小达人';

  /* R65：boot 加载开始即创建 AudioContext 并尝试 resume（无手势时 resume 会失败但无害；创建本身被允许） */
  try { SFX.unlock(); } catch (e) {}
  /* R63(2) 音乐：链接一打开直接尝试出声（首次被浏览器拦截则由下方多事件兜底解锁播放） */
  try { if (SFX.isEnabled()) SFX.bgmPlay('boot'); } catch (e) {}

  /* R63 仅电脑端（>760px）显示动画区与跑酷彩蛋 */
  const isPC = window.innerWidth > 760;
  const animCfg = _ldCfg.animation || {};
  const eggCfg = _ldCfg.runnerEgg || {};
  const wantAnim = isPC && animCfg.enabled !== false;
  const wantEgg = isPC && eggCfg.enabled !== false;

  /* R63 构建：垃圾分类小动画 + 橘子跑酷彩蛋（index.html 未注入容器时由 JS 兜底创建） */
  let animCtl = null;
  if (wantAnim) { try { animCtl = r63BuildSortAnim(boot); } catch (e) { animCtl = null; } }
  if (wantEgg) { try { r63BuildRunnerEgg(boot); } catch (e) {} }

  var done = 0, total = urls.length;
  var finished = false, preloadDone = false;

  /* 真正收起加载页（幂等） */
  function releaseNow() {
    if (finished) return;
    finished = true;
    if (animCtl && animCtl.destroy) { try { animCtl.destroy(); } catch (e) {} }
    boot.classList.add('is-done');
    /* R31 加载动画配乐：若加载曲在播则切换回首页曲 */
    if (SFX.isEnabled() && SFX.bgmNow() === 'boot') SFX.bgmPlay('home');
    setTimeout(function () { if (boot.parentNode) boot.parentNode.removeChild(boot); }, 550);
  }
  /* 放行闸门：预加载完成 且（动画播完一套 / 硬超时 / 用户跳过）才收起 */
  function gateRelease() {
    if (finished || !preloadDone) return;
    releaseNow();
  }

  /* 用户点击任意处跳过动画等待直接放行：
     - 点 #boot-tip 仍只切换文字；
     - 点彩蛋内部（跳跃/重开）不触发跳过；
     - 其余区域点击立即放行。 */
  boot.addEventListener('click', function (e) {
    if (tip && (e.target === tip || tip.contains(e.target))) return;
    if (e.target && e.target.closest && e.target.closest('#boot-runner-egg')) return;
    releaseNow();
  });

  function tick() {
    done += 1;
    var pct = Math.round((done / Math.max(1, total)) * 100);
    if (barFill) barFill.style.width = pct + '%';
    /* R64：把进度百分比写为 --r64-prog（设在 #boot 上，.boot-orange 才能继承到；
       .boot-bar 与 .boot-orange 是兄弟节点，设在 bar 上继承不到） */
    try {
      var bootEl = document.getElementById('boot');
      if (bootEl) bootEl.style.setProperty('--r64-prog', pct + '%');
    } catch (e) {}
    if (done >= total) enterAnimPhase();
  }

  /* R63 预加载完成 → 进入动画阶段（而非直接放行） */
  function enterAnimPhase() {
    if (preloadDone) return;
    preloadDone = true;
    if (!wantAnim || !animCtl) { releaseNow(); return; }   /* 无动画/非电脑：立即放行 */
    /* 有动画：等一套播完（onSetDone→gateRelease）；用户跳过/20s 硬超时强制放行 */
    animCtl.onSetDone = function () { gateRelease(); };
    setTimeout(function () { releaseNow(); }, 20000);       /* 动画阶段独立 20s 兜底，防卡死 */
    /* 不立即放行：等一套动画播完（onSetDone→gateRelease），或用户点击/20s 硬超时 */
  }

  if (total === 0) { enterAnimPhase(); }
  else {
    urls.forEach(function (u) {
      var im = new Image();
      im.onload = tick;
      im.onerror = tick;
      im.src = u;
    });
  }
  /* 兜底：8 秒内未加载完 → 进入动画阶段（而非直接放行） */
  setTimeout(enterAnimPhase, 8000);
})();

/* R63 首次交互解锁音频：pointerdown/keydown/touchstart 任一触发即解锁并播放加载曲；
   visibilitychange 永久监听：页面切回前台时 resume，若 bgm 被系统清掉则重播当前场景曲 */
(function () {
  /* R64：浏览器自动播放策略——首次手势即解锁并强制重启当前 BGM（此前首屏 bgmPlay 已把
     bgmName 置为 'boot'，但 ctx 被挂起无声；手势后 !SFX.bgmNow() 为假导致不重启）；
     页面切回前台同样 resume+兜底重播，确保一交互就出声、循环不断 */
  function r64RestartBgm() {
    try { SFX.unlock(); } catch (e) {}
    if (!SFX.isEnabled()) return;
    var cur = SFX.bgmNow();
    if (cur) { try { SFX.bgmStop(); } catch (e) {} try { SFX.bgmPlay(cur); } catch (e) {} return; }
    var boot = document.getElementById('boot');
    try { SFX.bgmPlay(boot ? 'boot' : 'home'); } catch (e) {}
  }
  var gestBound = ['pointerdown', 'keydown', 'touchstart'];
  function onGesture() {
    r64RestartBgm();
    gestBound.forEach(function (ev) { document.removeEventListener(ev, onGesture); });
  }
  gestBound.forEach(function (ev) { document.addEventListener(ev, onGesture, { passive: true }); });
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) return;
    r64RestartBgm();
  });
})();

/* R65 反馈9：声音开关按钮 #r65-sound-toggle（UI Agent 在 index.html 预置；此处兜底创建并事件委托绑定）
   点击 → SFX.unlock() + 若 bgmNow() 空则按当前场景 bgmPlay；切换 SFX.setEnabled；按钮态同步(is-muted/aria-label) */
(function r65SoundToggle() {
  function getBtn() {
    var b = document.getElementById('r65-sound-toggle');
    if (!b) {
      b = document.createElement('button');
      b.id = 'r65-sound-toggle';
      b.type = 'button';
      b.className = 'r65-sound-toggle';
      document.body.appendChild(b);
    }
    return b;
  }
  function sync() {
    var b = getBtn();
    var on = SFX.isEnabled();
    b.classList.toggle('is-muted', !on);
    b.setAttribute('aria-label', on ? '声音开（点击静音）' : '声音关（点击开启）');
    b.textContent = on ? '🔊' : '🔇';
  }
  document.addEventListener('click', function (e) {
    var t = e.target && e.target.closest ? e.target.closest('#r65-sound-toggle') : null;
    if (!t) return;
    var newOn = !SFX.isEnabled();
    SFX.setEnabled(newOn);
    if (newOn) {
      try { SFX.unlock(); } catch (e2) {}
      if (!SFX.bgmNow()) {
        var boot = document.getElementById('boot');
        try { SFX.bgmPlay(boot ? 'boot' : 'home'); } catch (e3) {}
      } else {
        try { var cur = SFX.bgmNow(); SFX.bgmStop(); SFX.bgmPlay(cur); } catch (e4) {}
      }
    }
    sync();
  });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', sync); else sync();
})();

/* ===== R63 加载页：垃圾分类小动画 + 橘子跑酷彩蛋（辅助函数，见文件末尾实现） ===== */

/* ============================================================
   R63 加载页：垃圾分类小动画 #boot-sort-anim（仅电脑）
   形象IP 拿垃圾 → 挠头苦想 → 四桶（标准标识）→ 头顶灯泡 → 投入对应桶 → 垃圾消失 → 欢呼跳跃
   ============================================================ */
function r63BuildSortAnim(boot) {
  var box = document.getElementById('boot-sort-anim');
  if (!box) {
    box = document.createElement('div');
    box.id = 'boot-sort-anim';
    boot.appendChild(box);
  }
  box.className = 'r63-anim';
  box.innerHTML =
    '<div class="r63-stage">' +
      '<div class="r63-bins">' +
        '<div class="r63-bin" data-cat="recyclable"><img src="assets/marks/mark-recyclable-new.jpg" alt="可回收物"></div>' +
        '<div class="r63-bin" data-cat="kitchen"><img src="assets/marks/mark-wet-new.jpg" alt="厨余垃圾"></div>' +
        '<div class="r63-bin" data-cat="hazardous"><img src="assets/marks/mark-hazardous-new.jpg" alt="有害垃圾"></div>' +
        '<div class="r63-bin" data-cat="other"><img src="assets/marks/mark-dry-new.jpg" alt="其他垃圾"></div>' +
      '</div>' +
      '<img class="r63-guide" alt="引导员">' +
      '<div class="r63-thought">？</div>' +
      '<div class="r63-bulb">💡</div>' +
      '<img class="r63-trash" alt="垃圾">' +
    '</div>';

  var guide = box.querySelector('.r63-guide');
  var trash = box.querySelector('.r63-trash');
  var thought = box.querySelector('.r63-thought');
  var bulb = box.querySelector('.r63-bulb');
  var bins = box.querySelectorAll('.r63-bin');

  var GUIDE = 'assets/avatar/candy/guide-candy-final.png';
  var CHEER = 'assets/avatar/candy/cheer-candy.png';
  var OOPS  = 'assets/avatar/candy/oops-candy.png';

  /* 垃圾素材池：(物品图, 正确分类)。四类各取若干，随机抽，保证 ≥3 套不同 */
  var POOL = [
    { img: 'assets/items/recyclable-2.png', cat: 'recyclable' },  /* 塑料瓶 */
    { img: 'assets/items/recyclable-0.png', cat: 'recyclable' },  /* 旧报纸 */
    { img: 'assets/items/recyclable-1.png', cat: 'recyclable' },  /* 易拉罐 */
    { img: 'assets/items/kitchen-0.png', cat: 'kitchen' },        /* 香蕉皮 */
    { img: 'assets/items/kitchen-1.png', cat: 'kitchen' },        /* 苹果核 */
    { img: 'assets/items/kitchen-4.png', cat: 'kitchen' },        /* 鸡蛋壳 */
    { img: 'assets/items/hazardous-0.png', cat: 'hazardous' },    /* 废电池 */
    { img: 'assets/items/hazardous-1.png', cat: 'hazardous' },    /* 过期药品 */
    { img: 'assets/items/other-0.png', cat: 'other' },             /* 烟头 */
    { img: 'assets/items/other-3.png', cat: 'other' }             /* 用过的纸巾 */
  ];

  var timers = [];
  var alive = true;
  function later(ms, fn) {
    var t = setTimeout(function () { if (alive) fn(); }, ms);
    timers.push(t);
  }

  var ctl = { onSetDone: null, destroy: function () { alive = false; timers.forEach(clearTimeout); timers = []; } };

  var usedIdx = [];
  function pickSet() {
    var avail = [];
    for (var i = 0; i < POOL.length; i++) if (usedIdx.indexOf(i) === -1) avail.push(i);
    if (!avail.length) { usedIdx = []; avail = POOL.map(function (_, i) { return i; }); }
    return avail[Math.floor(Math.random() * avail.length)];
  }

  function resetStage(item) {
    bins.forEach(function (b) { b.classList.remove('r63-hot'); });
    guide.classList.remove('r63-jump', 'r63-thinking');
    thought.style.opacity = '0';
    bulb.style.opacity = '0';
    trash.style.transition = 'none';
    trash.style.transform = 'translate(0,0) scale(1)';
    trash.style.opacity = '0';
    trash.src = item.img;
  }

  function runSet() {
    if (!alive) return;
    var idx = pickSet();
    usedIdx.push(idx);
    var item = POOL[idx];

    /* 开场：25% 概率先沮丧(oops)一下再正经(guide)，增加随机变化 */
    if (Math.random() < 0.25) {
      guide.src = OOPS;
      guide.classList.add('r63-oops-shake');
      later(900, function () {
        guide.classList.remove('r63-oops-shake');
        guide.src = GUIDE;
      });
    } else {
      guide.src = GUIDE;
    }

    resetStage(item);
    /* t0.3s：拿垃圾（垃圾飘到引导员手边） */
    later(300, function () { trash.style.opacity = '1'; });
    /* t2.4s：挠头苦想（？气泡 + 引导员左右晃） */
    later(2400, function () {
      thought.style.opacity = '1';
      if (guide.src.indexOf('guide') !== -1) guide.classList.add('r63-thinking');
    });
    /* t4.6s：想清楚了，头顶冒灯泡 */
    later(4600, function () {
      thought.style.opacity = '0';
      bulb.style.opacity = '1';
    });
    /* t6.2s：把垃圾投入对应分类的桶 */
    later(6200, function () {
      bulb.style.opacity = '0';
      var target = box.querySelector('.r63-bin[data-cat="' + item.cat + '"]');
      if (!target) return;
      var tb = target.getBoundingClientRect();
      var rb = trash.getBoundingClientRect();
      var dx = (tb.left + tb.width / 2) - (rb.left + rb.width / 2);
      var dy = (tb.top + tb.height / 2) - (rb.top + rb.height / 2);
      trash.style.transition = 'transform 1.05s cubic-bezier(.55,.06,.68,.19), opacity .5s ease .95s';
      trash.style.transform = 'translate(' + dx + 'px,' + dy + 'px) scale(.35) rotate(140deg)';
      trash.style.opacity = '0';
      if (typeof SFX !== 'undefined' && SFX.move) { try { SFX.move(); } catch (e) {} }
    });
    /* t7.6s：垃圾消失，对应桶高亮 */
    later(7600, function () {
      var target = box.querySelector('.r63-bin[data-cat="' + item.cat + '"]');
      if (target) target.classList.add('r63-hot');
    });
    /* t8.2s：引导员欢呼跳跃（五指 cheer） */
    later(8200, function () {
      guide.src = CHEER;
      guide.classList.remove('r63-thinking');
      guide.classList.add('r63-jump');
      if (typeof SFX !== 'undefined' && SFX.score) { try { SFX.score(); } catch (e) {} }
    });
    /* t13.5s：一套结束 → 通知外层放行（可继续下一套，若遮罩还在） */
    later(13500, function () {
      if (ctl.onSetDone) { try { ctl.onSetDone(); } catch (e) {} }
      if (alive) runSet();   /* 循环播下一套，直到遮罩被移除（destroy 置 alive=false） */
    });
  }

  runSet();
  return ctl;
}

/* ============================================================
   R63 加载页：橘子跑酷彩蛋 #boot-runner-egg（仅电脑，仿谷歌小恐龙）
   ============================================================ */
function r63BuildRunnerEgg(boot) {
  var box = document.getElementById('boot-runner-egg');
  if (!box) {
    box = document.createElement('div');
    box.id = 'boot-runner-egg';
    boot.appendChild(box);
  }
  box.className = 'r63-runner';
  box.innerHTML =
    '<div class="r63-run-hud">' +
      '<span class="r63-run-score">得分 <b>0</b></span>' +
      '<button class="r63-run-restart" type="button">↻ 重开</button>' +
    '</div>' +
    '<div class="r63-run-field">' +
      '<div class="r63-run-ground"></div>' +
      '<div class="r63-run-player">🍊</div>' +
      '<div class="r63-run-obstacles"></div>' +
      '<div class="r63-run-over">点击/空格 开始</div>' +
    '</div>' +
    '<div class="r63-run-hint">空格 / ↑ / 点击场地 跳跃</div>';

  var field = box.querySelector('.r63-run-field');
  var player = box.querySelector('.r63-run-player');
  var obsLayer = box.querySelector('.r63-run-obstacles');
  var scoreEl = box.querySelector('.r63-run-score b');
  var overEl = box.querySelector('.r63-run-over');
  var restartBtn = box.querySelector('.r63-run-restart');

  var W = 360, H = 150, GROUND = 18;   /* 场地高 / 地面高度 */
  var state = { running: false, over: false, score: 0, y: 0, vy: 0, obs: [], spawnIn: 0, raf: 0, last: 0 };
  var GRAV = 0.55, JUMP = -10.5, SPEED = 3.4;

  function reset() {
    state.running = false; state.over = false; state.score = 0;
    state.y = 0; state.vy = 0; state.obs = []; state.spawnIn = 60;
    obsLayer.innerHTML = '';
    player.style.transform = 'translateY(0)';
    scoreEl.textContent = '0';
    overEl.style.display = 'block';
    overEl.textContent = '点击/空格 开始';
  }
  function start() {
    if (state.over) reset();
    state.running = true;
    overEl.style.display = 'none';
    if (!state.last) { state.last = performance.now(); state.raf = requestAnimationFrame(loop); }
  }
  function jump() {
    if (!state.running) { start(); return; }
    if (state.over) { reset(); return; }
    if (state.y <= 0.5) state.vy = JUMP;
  }
  function gameOver() {
    state.over = true; state.running = false;
    overEl.style.display = 'block';
    overEl.textContent = '撞到啦！得分 ' + state.score;
  }
  function loop(now) {
    state.raf = requestAnimationFrame(loop);
    /* 重力 */
    state.vy += GRAV; state.y -= state.vy;
    if (state.y <= 0) { state.y = 0; state.vy = 0; }
    player.style.transform = 'translateY(' + (-state.y) + 'px)';

    /* 生成障碍 */
    state.spawnIn--;
    if (state.spawnIn <= 0) {
      state.spawnIn = 60 + Math.floor(Math.random() * 60);
      var ob = document.createElement('div');
      ob.className = 'r63-run-ob';
      ob.style.height = (18 + Math.random() * 22) + 'px';
      ob.dataset.x = W;
      obsLayer.appendChild(ob);
    }
    /* 移动障碍 + 碰撞 */
    var playerX = 34, playerH = 34, playerW = 30;
    var els = obsLayer.children;
    for (var i = 0; i < els.length; i++) {
      var el = els[i];
      var x = parseFloat(el.dataset.x) - SPEED;
      el.dataset.x = x;
      el.style.transform = 'translateX(' + x + 'px)';
      var obH = el.offsetHeight || 24;
      /* 碰撞盒：玩家底部 y=state.y */
      var hitX = (x < playerX + playerW && x + 16 > playerX);
      var hitY = (state.y < obH - 4);
      if (hitX && hitY) { gameOver(); return; }
      /* 越过得分 */
      if (!el.dataset.pass && x + 16 < playerX) { el.dataset.pass = '1'; state.score++; scoreEl.textContent = state.score; }
      if (x < -20) { el.remove(); i--; }
    }
  }

  field.addEventListener('click', function (e) { e.stopPropagation(); jump(); });
  restartBtn.addEventListener('click', function (e) { e.stopPropagation(); reset(); start(); });
  function onKey(e) {
    if (e.code === 'Space' || e.code === 'ArrowUp' || e.key === 'ArrowUp') {
      /* 仅当彩蛋可见且在加载页时响应，避免影响游戏内操作 */
      if (document.getElementById('boot')) { e.preventDefault(); jump(); }
    }
  }
  document.addEventListener('keydown', onKey);

  reset();
  return {
    destroy: function () {
      cancelAnimationFrame(state.raf);
      document.removeEventListener('keydown', onKey);
    }
  };
}
